// SculptForge - open source digital sculpting
// SPDX-License-Identifier: GPL-3.0-or-later
//
// The Japanese interface (日本語). The English text is the key (I18n.h); a label without an entry stays in English.
// First pass machine-translated and critiqued, native review wanted: corrections welcome (a pull request or an issue).
//
// Conventions:
//   - Names of tools, brushes and products stay in English: Quad Remesh, Forge Spheres, Lit Sphere, Splats, Clay Block
//     and every other brush, VDM, Alpha. Generic words are translated: パーツ (Part), ライブラリ (Library), 頂点ペイント
//     (Vertex Paint), フェイスグループ (Face Groups), 環境設定 (Preferences), 元に戻す (undo), ストローク (stroke).
//   - Sentences and tooltips are polite form (です・ます); buttons and labels are short noun or dictionary forms.
//   - No space between Japanese and Latin text or numbers, Japanese punctuation (、。) and 「」 quotes, except right after a
//     printf conversion or a literal %, where ASCII punctuation keeps the conversions the same.
//   - printf conversions (%d, %.1f, %s, %%) stay in the same order: tests check every entry.
//   - Every character has to be in assets/fonts/NotoSansJP-UI.otf: after changing this table, run
//     tools/i18n/subset_cjk_font.py (a test lists what is missing).
// The entries follow the Simplified Chinese table's order, one entry per English text.
#include "app/I18n.h"

#include <iterator>

